params.workflow_source = null
workflow {
    def text = file(params.workflow_source).text
    def marker = 'def ch_sketch_input = ch_library.flatMap '
    def start = text.indexOf(marker)
    assert start >= 0
    start += marker.length()
    def end = text.indexOf('\n\n    SOURMASH_SKETCH', start)
    assert end > start
    def fragment = text.substring(start, end).trim().replace('{ meta, genomes ->', '{ meta, genomes, batch_size ->')
    def mapping = new GroovyShell().evaluate(fragment)
    def genomes = [file('z.fna'), file('a.fna'), file('m.fna')]
    def before = genomes.collect { it.toString() }
    def batches = mapping.call([id: 'reference'], genomes, 2)
    assert genomes.collect { it.toString() } == before : 'shared genome list changed'
    assert batches.size() == 2
    assert batches[0][0] == [id: 'reference_1', db: 'reference']
    assert batches[1][0] == [id: 'reference_2', db: 'reference']
    assert batches[0][1].collect { it.name } == ['a.fna', 'm.fna']
    assert batches[1][1].collect { it.name } == ['z.fna']
    println 'SOURCE_SORT_CONTROL_PASSED: original list unchanged; sorted batches complete'
}
